<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import Icon from './Icon.vue'
import type { MediaAsset } from '../core/types.ts'
import type { AiGenerationRequest, AiProvider } from '../core/ai.ts'
import { aiState, aiServiceError, observeAi, generateAi, stopAiJob, aiDuration, aiBytes, aiModelStateNames } from '../core/ai-service.ts'
import { pickMediaAssets, revealMediaAsset } from '../native.ts'

const props = defineProps<{ provider: 'image' | 'music'; native: boolean; active: boolean; projectTitle: string; disabled?: boolean }>()
const emit = defineEmits<{ 'open-models': [provider: AiProvider]; 'add-asset': [asset: MediaAsset]; 'add-timeline': [asset: MediaAsset]; 'edit-image': [asset: MediaAsset]; status: [message: string] }>()
const modelId = ref(''), prompt = ref(''), negativePrompt = ref(''), lyrics = ref(''), instrumental = ref(false)
const imageMode = ref<'text' | 'image'>('text'), inputAsset = ref<MediaAsset>(), size = ref('512x512'), strength = ref(.65)
const steps = ref(props.provider === 'image' ? 9 : 8), guidance = ref(4), seed = ref(42), seconds = ref(30), bpm = ref<number>(), language = ref('zh'), keyScale = ref(''), lowMemory = ref(true)
const starting = ref(false), selecting = ref(false), error = ref(''), selectedJob = ref(''), selectedAsset = ref(''), cancelling = ref('')
let release: (() => void) | undefined, saveTimer: ReturnType<typeof setTimeout> | undefined
const image = computed(() => props.provider === 'image'), heading = computed(() => image.value ? '图像生成' : '歌曲生成')
const models = computed(() => aiState.value.models.filter(model => model.provider === props.provider))
const model = computed(() => models.value.find(item => item.id === modelId.value))
const jobs = computed(() => aiState.value.jobs.filter(job => job.provider === props.provider && job.kind === 'generation').slice().sort((a,b) => b.startedAt-a.startedAt))
const working = computed(() => starting.value || jobs.value.some(job=>job.state==='running'))
const job = computed(() => jobs.value.find(item => item.id === selectedJob.value) ?? jobs.value[0])
const result = computed(() => job.value?.assets.find(asset => asset.id === selectedAsset.value) ?? job.value?.assets[0])
const supportsNegative = computed(() => modelId.value === 'qwen-image')
const unavailable = computed(() => !props.native ? '本地生成需要桌面端。' : !model.value ? '请在模型中心选择并下载模型。' : model.value.state !== 'ready' ? `${model.value.name}：${aiModelStateNames[model.value.state]}，请先在模型中心准备模型。` : model.value.runtime.state === 'unsupported' ? model.value.runtime.reason || '当前设备不支持这个模型。' : '')
const invalid = computed(() => !prompt.value.trim() ? '请描述你想生成的内容。' : prompt.value.length > (image.value ? 6000 : 4096) ? '内容描述超过模型支持的长度。' : lyrics.value.length > 6000 ? '歌词不能超过 6000 字。' : !Number.isInteger(steps.value) || steps.value < 1 || steps.value > 100 ? '生成步数应为 1–100 的整数。' : !Number.isInteger(seed.value) || seed.value < 0 || seed.value > 4294967295 ? '随机种子无效。' : !image.value && (!Number.isFinite(seconds.value) || seconds.value < 10 || seconds.value > 180) ? '歌曲时长应为 10–180 秒。' : image.value && imageMode.value === 'image' && !inputAsset.value ? '请选择作为起点的图片。' : !image.value && !instrumental.value && !lyrics.value.trim() ? '请输入歌词，或切换为纯音乐。' : '')
const canGenerate = computed(() => !props.disabled && !working.value && !unavailable.value && !invalid.value)
const draftKey = computed(() => `open-media:ai-${props.provider}-draft:v1`)
watch(models, values => { if (!modelId.value && values[0]) { modelId.value = values[0].id; chooseModel() } })
function chooseModel(): void { steps.value = image.value ? modelId.value === 'qwen-image' ? 30 : 9 : modelId.value.includes('sft') ? 50 : 8 }
watch(() => props.active, active => { if (!active) document.querySelectorAll<HTMLMediaElement>(`[data-ai-provider="${props.provider}"] audio`).forEach(element=>element.pause()) })
function persist(): void {
  try { localStorage.setItem(draftKey.value, JSON.stringify({ modelId:modelId.value,prompt:prompt.value,negativePrompt:negativePrompt.value,lyrics:lyrics.value,instrumental:instrumental.value,imageMode:imageMode.value,size:size.value,strength:strength.value,steps:steps.value,guidance:guidance.value,seed:seed.value,seconds:seconds.value,bpm:bpm.value,language:language.value,keyScale:keyScale.value,lowMemory:lowMemory.value })) }
  catch { error.value = '生成参数草稿暂时无法保存到本机，请保留提示词。' }
}
watch([modelId,prompt,negativePrompt,lyrics,instrumental,imageMode,size,strength,steps,guidance,seed,seconds,bpm,language,keyScale,lowMemory],()=>{clearTimeout(saveTimer);saveTimer=setTimeout(persist,400)})
onMounted(() => {
  try {
    const draft = JSON.parse(localStorage.getItem(draftKey.value) || '{}')
    if (typeof draft.modelId==='string') modelId.value=draft.modelId
    for (const [key,target] of [['prompt',prompt],['negativePrompt',negativePrompt],['lyrics',lyrics],['language',language],['keyScale',keyScale]] as const) if (typeof draft[key]==='string') target.value=draft[key].slice(0,key==='prompt'&&!image.value?4096:6000)
    for (const [key,target,min,max] of [['steps',steps,1,100],['guidance',guidance,0,20],['seed',seed,0,4294967295],['seconds',seconds,10,180],['strength',strength,.1,1]] as const) if (Number.isFinite(draft[key])) target.value=Math.max(min,Math.min(max,draft[key]))
    if (['512x512','768x768','1024x1024','1024x576','576x1024'].includes(draft.size)) size.value=draft.size
    if (['text','image'].includes(draft.imageMode)) imageMode.value=draft.imageMode
    if (typeof draft.instrumental==='boolean') instrumental.value=draft.instrumental
    if (typeof draft.lowMemory==='boolean') lowMemory.value=draft.lowMemory
    if (Number.isFinite(draft.bpm) && draft.bpm>=30 && draft.bpm<=240) bpm.value=draft.bpm
  } catch { /* Ignore an incomplete local parameter draft. */ }
  release=observeAi()
})
onBeforeUnmount(()=>{release?.();clearTimeout(saveTimer);persist()})
async function pickImage(): Promise<void> {
  selecting.value=true;error.value=''
  try { const assets=await pickMediaAssets(); const asset=assets.find(item=>item.kind==='image'); if(asset) inputAsset.value=asset; else if(assets.length) error.value='请选择图片文件。' }
  catch(cause){error.value=String(cause)} finally{selecting.value=false}
}
async function generate(): Promise<void> {
  if(!canGenerate.value)return
  starting.value=true;error.value=''
  const [width,height]=size.value.split('x').map(Number)
  const request:AiGenerationRequest={requestId:crypto.randomUUID(),modelId:modelId.value,prompt:prompt.value.trim(),steps:steps.value,seed:seed.value,lowMemory:lowMemory.value,
    ...(image.value?{width,height,negativePrompt:supportsNegative.value?negativePrompt.value:undefined,guidance:supportsNegative.value?guidance.value:0,inputAsset:imageMode.value==='image'?inputAsset.value:undefined,strength:imageMode.value==='image'?strength.value:undefined}:{lyrics:instrumental.value?'':lyrics.value.trim(),instrumental:instrumental.value,seconds:seconds.value,bpm:bpm.value||undefined,language:language.value,keyScale:keyScale.value.trim()||undefined})}
  try{const next=await generateAi({provider:props.provider,request});selectedJob.value=next.id;emit('status',`${heading.value}任务已提交，可在 AI 模型中心查看或取消`)}catch(cause){error.value=cause instanceof Error?cause.message:String(cause)}finally{starting.value=false}
}
async function cancel(id:string):Promise<void>{cancelling.value=id;try{await stopAiJob(id)}catch(cause){error.value=String(cause)}finally{cancelling.value=''}}
async function reveal(asset:MediaAsset):Promise<void>{try{await revealMediaAsset(asset)}catch(cause){error.value=String(cause)}}
</script>

<template>
  <section class="ai-generation-workspace" :data-ai-provider="provider" :data-testid="`${provider}-generation-workspace`">
    <header class="ai-generation-heading"><div><h1><Icon :name="image ? 'image' : 'audio'" :size="25"/>{{ heading }}</h1><p>{{ image ? '描述画面，或从一张图片开始创作。' : '描述风格、乐器与氛围，创作歌曲或纯音乐。' }}</p></div><button @click="emit('open-models',provider)"><Icon name="layers" :size="16"/>AI 模型中心</button></header>
    <div class="ai-generation-columns"><div class="ai-generation-compose">
      <section class="ai-generation-card"><h2>生成模型</h2><div class="ai-model-select"><select v-model="modelId" :disabled="working" aria-label="生成模型" @change="chooseModel"><option v-if="!models.length" value="">请在模型中心下载模型</option><option v-for="item in models" :key="item.id" :value="item.id">{{ item.name }} · {{ aiModelStateNames[item.state] }}</option></select><button @click="emit('open-models',provider)">管理模型</button></div><p v-if="model" class="ai-generation-muted">{{ model.hardware }} · 模型 {{ aiBytes(model.size) }}</p><p v-if="model?.runtime.reason" class="ai-generation-muted">{{ model.runtime.reason }}</p><p class="ai-generation-muted">模型和运行环境按需下载，完成后所有工作区共用。</p></section>
      <section class="ai-generation-card"><div class="ai-generation-modes" role="group" :aria-label="`${heading}方式`"><template v-if="image"><button :disabled="working" :aria-pressed="imageMode==='text'" @click="imageMode='text'">文生图</button><button :disabled="working || (!!model && !model.capabilities.includes('image-to-image'))" :aria-pressed="imageMode==='image'" @click="imageMode='image'">图生图</button></template><template v-else><button :disabled="working" :aria-pressed="!instrumental" @click="instrumental=false">歌曲</button><button :disabled="working" :aria-pressed="instrumental" @click="instrumental=true">纯音乐</button></template></div>
        <div v-if="image && imageMode==='image'" class="ai-input-image"><button :disabled="!native || working || selecting" @click="pickImage"><img v-if="inputAsset" :src="inputAsset.url" :alt="inputAsset.name"/><Icon v-else name="image" :size="30"/><span>{{ inputAsset?.name || '选择起始图片' }}</span></button><p class="ai-generation-muted">保留原图构图进行重绘；这不是针对局部文字指令的图片编辑。</p></div>
        <label class="ai-generation-label">{{ image ? '画面描述' : '音乐描述' }}<textarea v-model="prompt" :disabled="working" :aria-label="image ? '图像提示词' : '音乐提示词'" :maxlength="image ? 6000 : 4096" rows="5" :placeholder="image ? '例如：蓝绿色玻璃温室，清晨的柔和光线，大片植物叶片，安静的电影感构图' : '例如：温暖的独立流行，钢琴与木吉他，轻柔女声，舒缓开场、副歌逐渐明亮'"/></label>
        <label v-if="image && supportsNegative" class="ai-generation-label">排除内容<textarea v-model="negativePrompt" :disabled="working" aria-label="图像负向提示词" maxlength="4000" rows="2" placeholder="可选：不希望出现的元素或画面问题"/></label>
        <label v-if="!image && !instrumental" class="ai-generation-label">歌词<textarea v-model="lyrics" :disabled="working" aria-label="歌曲歌词" maxlength="6000" rows="7" placeholder="[Verse]\n输入主歌歌词\n\n[Chorus]\n输入副歌歌词"/><small>支持分段标记。请提供歌词，或切换为纯音乐。</small></label>
        <div class="ai-generation-parameters"><template v-if="image"><label>画幅<select v-model="size" :disabled="working" aria-label="生成图像尺寸"><option value="512x512">512 × 512</option><option value="768x768">768 × 768</option><option value="1024x1024">1024 × 1024</option><option value="1024x576">1024 × 576</option><option value="576x1024">576 × 1024</option></select></label><label v-if="imageMode==='image'">重绘强度<input v-model.number="strength" :disabled="working" aria-label="重绘强度" type="number" min="0.1" max="1" step="0.05"/></label><label v-if="supportsNegative">提示词引导<input v-model.number="guidance" :disabled="working" aria-label="提示词引导" type="number" min="0" max="20" step="0.5"/></label></template><template v-else><label>时长（秒）<input v-model.number="seconds" :disabled="working" aria-label="歌曲时长" type="number" min="10" max="180" step="1"/></label><label>节拍（可选）<input v-model.number="bpm" :disabled="working" aria-label="音乐节拍" type="number" min="30" max="240" placeholder="自动"/></label><label v-if="!instrumental">演唱语言<select v-model="language" :disabled="working" aria-label="演唱语言"><option value="zh">中文</option><option value="en">英语</option><option value="ja">日语</option><option value="ko">韩语</option><option value="es">西班牙语</option></select></label><label>调性（可选）<input v-model="keyScale" :disabled="working" aria-label="音乐调性" maxlength="40" placeholder="例如 C major"/></label></template><label>生成步数<input v-model.number="steps" :disabled="working" aria-label="生成步数" type="number" min="1" max="100"/></label><label>随机种子<input v-model.number="seed" :disabled="working" aria-label="生成随机种子" type="number" min="0" max="4294967295"/></label></div>
        <label class="ai-low-memory"><input v-model="lowMemory" :disabled="working" type="checkbox"/>低内存模式<small>减少权重常驻占用，生成可能更慢；不保证峰值内存。</small></label>
        <p v-if="error || aiServiceError" class="ai-generation-error" role="alert">{{ error || aiServiceError }}</p><div class="ai-generation-submit"><p>{{ unavailable || invalid || '优先使用可用 GPU，无法运行时报告原因并尝试 CPU。' }}</p><button class="primary" :disabled="!canGenerate" data-testid="ai-generation-start" @click="generate"><span v-if="starting" class="spinner small"/><Icon v-else name="sparkles" :size="16"/>{{ starting ? '正在提交…' : '开始生成' }}</button></div>
      </section>
    </div><aside class="ai-generation-card ai-generation-results"><header><h2>生成结果</h2><small>{{ jobs.length }} 个任务</small></header><div v-if="!jobs.length" class="ai-generation-empty"><Icon :name="image ? 'image' : 'audio'" :size="42"/><strong>{{ image ? '让画面从描述中诞生' : '为作品写一段旋律' }}</strong><p>生成结果保存在本机，可预览并加入当前剪辑项目。</p></div><div v-else class="ai-generation-job-list"><article v-for="item in jobs" :key="item.id" :class="{selected:job?.id===item.id}"><button class="ai-generation-job-heading" @click="selectedJob=item.id"><strong>{{ models.find(entry=>entry.id===item.modelId)?.name || heading }}</strong><span>{{ ({running:'生成中',completed:'已完成',failed:'失败',cancelled:'已取消'})[item.state] }}</span></button><p>{{ item.stage }} · {{ aiDuration(item.elapsedSeconds) }}</p><progress v-if="item.state==='running'" :value="item.progress" max="1" aria-label="生成任务进度"/><p v-if="item.error" class="ai-generation-error">{{ item.error }}</p><p v-if="item.warning" class="ai-generation-muted">{{ item.warning }}</p><button v-if="item.state==='running' && item.cancelable" :disabled="cancelling===item.id" @click="cancel(item.id)">{{ cancelling===item.id?'正在取消…':'取消生成' }}</button></article></div>
      <div v-if="result" class="ai-generation-result"><img v-if="result.kind==='image'" :src="result.url" :alt="result.name"/><audio v-else :key="result.id" :src="result.url" controls preload="metadata"/><label v-if="job && job.assets.length>1">选择结果<select v-model="selectedAsset"><option v-for="asset in job.assets" :key="asset.id" :value="asset.id">{{ asset.name }}</option></select></label><strong>{{ result.name }}</strong><small>{{ image ? `${result.width} × ${result.height}` : aiDuration(result.duration) }}</small><div class="ai-generation-result-actions"><button :disabled="disabled" @click="emit('add-asset',result)"><Icon name="import" :size="14"/>加入素材</button><button :disabled="disabled" @click="emit('add-timeline',result)"><Icon name="plus" :size="14"/>加入时间线</button><button v-if="image" :disabled="disabled" @click="emit('edit-image',result)"><Icon name="image" :size="14"/>编辑图片</button><button title="打开文件夹" aria-label="打开生成结果文件夹" @click="reveal(result)"><Icon name="folder" :size="15"/></button></div><p class="ai-generation-muted">当前项目：{{ projectTitle }}</p></div>
    </aside></div>
  </section>
</template>

<style scoped>
.ai-generation-workspace{flex:1;min-height:0;overflow:auto;padding:24px 28px 32px;overscroll-behavior:contain;scrollbar-width:thin}.ai-generation-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:22px}.ai-generation-heading h1{display:flex;align-items:center;gap:10px;font-size:23px;margin:0}.ai-generation-heading h1 svg{color:var(--ui-accent)}.ai-generation-heading p{font-size:12px;color:var(--ui-muted);margin:9px 0 0}.ai-generation-heading>button{font-size:11px;padding:8px 12px;flex:none}.ai-generation-columns{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(280px,.85fr);gap:20px;align-items:start;max-width:1600px;margin:auto}.ai-generation-compose{display:grid;gap:16px;min-width:0}.ai-generation-card{border:1px solid var(--ui-line);border-radius:12px;padding:18px;background:var(--ui-surface);min-width:0}.ai-generation-card h2{font-size:13px;margin:0 0 14px}.ai-model-select{display:flex;gap:8px}.ai-model-select select{flex:1;min-width:0}.ai-model-select button{font-size:11px;white-space:nowrap}.ai-generation-muted{font-size:11px;line-height:1.8;color:var(--ui-muted)}.ai-generation-modes{display:flex;gap:6px;margin-bottom:18px}.ai-generation-modes button{flex:1;padding:8px;font-size:12px}.ai-generation-modes button[aria-pressed=true]{color:var(--ui-accent);border-color:var(--ui-accent);background:var(--ui-accent-soft)}.ai-generation-label{display:grid;gap:8px;font-size:12px;margin:15px 0}.ai-generation-label textarea{display:block;width:100%;min-height:80px;resize:vertical;padding:11px 12px;border:1px solid var(--ui-line);border-radius:8px;background:var(--ui-surface-2);color:var(--ui-text);font-size:12px;line-height:1.8;font-family:inherit}.ai-generation-label small{font-size:10px;color:var(--ui-muted)}.ai-generation-parameters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding-top:16px;border-top:1px solid var(--ui-line);margin-top:18px}.ai-generation-parameters label{display:grid;gap:7px;font-size:11px;min-width:0}.ai-generation-parameters input,.ai-generation-parameters select{min-width:0;width:100%;height:var(--ui-control-height);font-size:var(--ui-control-font-size)}.ai-low-memory{display:flex;align-items:center;flex-wrap:wrap;gap:7px;font-size:11px;margin:18px 0}.ai-low-memory input{accent-color:var(--ui-accent)}.ai-low-memory small{font-size:10px;color:var(--ui-muted)}.ai-generation-submit{display:flex;justify-content:space-between;gap:12px;align-items:center;border-top:1px solid var(--ui-line);padding-top:15px}.ai-generation-submit p{font-size:10px;line-height:1.7;color:var(--ui-muted);margin:0}.ai-generation-submit button{font-size:12px;padding:9px 14px;white-space:nowrap;flex:none}.ai-generation-error{font-size:11px;line-height:1.7;color:var(--ui-danger);overflow-wrap:anywhere}.ai-input-image>button{display:flex;flex-direction:column;gap:8px;width:100%;min-height:120px;border-style:dashed;color:var(--ui-muted);font-size:11px;padding:12px}.ai-input-image img{width:100%;height:150px;object-fit:contain}.ai-input-image p{font-size:10px}.ai-generation-results{position:sticky;top:0}.ai-generation-results>header{display:flex;justify-content:space-between;gap:12px}.ai-generation-results>header small{font-size:10px;color:var(--ui-muted)}.ai-generation-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;min-height:320px;text-align:center;color:var(--ui-muted)}.ai-generation-empty svg{color:var(--ui-accent);opacity:.65}.ai-generation-empty strong{font-size:13px}.ai-generation-empty p{max-width:240px;font-size:11px;line-height:1.8}.ai-generation-job-list{display:grid;gap:10px;max-height:300px;overflow:auto;scrollbar-width:thin}.ai-generation-job-list article{border:1px solid var(--ui-line);border-radius:8px;padding:11px}.ai-generation-job-list article.selected{border-color:var(--ui-accent)}.ai-generation-job-heading{display:flex;justify-content:space-between;align-items:center;gap:8px;border:0;padding:0;background:transparent;width:100%;font-size:11px;text-align:left}.ai-generation-job-heading strong{font-size:11px;overflow-wrap:anywhere}.ai-generation-job-heading span{white-space:nowrap;color:var(--ui-muted)}.ai-generation-job-list p{font-size:10px;line-height:1.7}.ai-generation-job-list article>button:last-child:not(:first-child){font-size:10px;padding:4px 8px}.ai-generation-job-list progress{width:100%;height:5px;accent-color:var(--ui-accent)}.ai-generation-result{display:grid;gap:10px;border-top:1px solid var(--ui-line);margin-top:18px;padding-top:18px}.ai-generation-result>img{width:100%;max-height:440px;object-fit:contain;border-radius:8px;background:var(--ui-surface-2)}.ai-generation-result audio{width:100%}.ai-generation-result>strong{font-size:12px;overflow-wrap:anywhere}.ai-generation-result>small{font-size:10px;color:var(--ui-muted)}.ai-generation-result label{display:grid;gap:6px;font-size:11px}.ai-generation-result-actions{display:flex;gap:7px;flex-wrap:wrap}.ai-generation-result-actions button{font-size:10px;padding:6px 9px}.ai-generation-result-actions button:last-child{margin-left:auto}.ai-generation-result .ai-generation-muted{margin:0}@media(max-width:1050px){.ai-generation-workspace{padding:18px}.ai-generation-columns{grid-template-columns:1fr}.ai-generation-results{position:static}}@media(max-width:560px){.ai-generation-workspace{padding:12px}.ai-generation-heading{align-items:flex-start}.ai-generation-heading h1{font-size:19px}.ai-generation-heading>button{font-size:10px;padding:7px}.ai-generation-parameters{grid-template-columns:repeat(2,minmax(0,1fr))}.ai-generation-card{padding:13px}}
</style>
